        EventAdapter["Event Adapter<br/>(Reactive messaging library)"]
        PersistenceAdapter["Persistence Adapter<br/>(Hibernate / Panache)"]
        ServiceDB[("Service Database<br/>(Relational store)")]
    end

    CP["Citizen Portal"]
